/**
 * @method
 * @name scwin.checkIsuCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param Name
 * @returns
 * @hidden N
*/
scwin.checkIsuCd = async function (Name) {
    /* sdd-asis-lifecycle:begin checkIsuCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.str.getByteLength(Name.getValue()) > 0) {
        if ($c.str.getByteLength(Name.getValue()) != 12) {
            await $c.win.alert("해외증서ISIN이 올바르지 않습니다.(12자리)");
            setTimeout(function() {
                    $("#ipt_glblIsinCd").select();
                }, 10);
            return;
        }
        if (!await scwin.checkNumUpperEnglish(Name, '해외증서ISIN')) {
            return;
        }
        const sendUrl = "/stdcd/subwarr.do?method=checkIsinCheckDisit";
        $.ajax({ type: "POST", async: false, url: sendUrl, data: $("#JLDINF10400").serialize(), success: async function(data) {
                    result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    if (result.sendResult === "N1") {
                        await $c.win.alert("입력된 해외증서ISIN과 동일한 코드가 존재합니다. 다시입력해주세요");
                        setTimeout(function() {
                                $("#ipt_glblIsinCd").select();
                            }, 10);
                        return;
                    } else {
                        if (result.sendResult === "N2") {
                            await $c.win.alert("입력된 해외증서ISIN이 유효하지 않습니다. 다시입력해주세요");
                            setTimeout(function() {
                                    $("#ipt_glblIsinCd").select();
                                }, 10);
                            return;
                        } else {

                        }
                    }
                }, error: async function(request, status, error) {
                    await $c.win.alert("현재 표준코드를 점검 할 수 없습니다. 관리자에게 문의하십시오.");
                    return;
                }, complete: function() {

                } });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkNumUpperEnglish
 * @author Inswave
 * @date 2026. 09. 29
 * @param aObj aDesc
 * @returns
 * @hidden N
*/
scwin.checkNumUpperEnglish = async function (aObj, aDesc) {
    /* sdd-asis-lifecycle:begin checkNumUpperEnglish — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const val = aObj.value;
    const len = val.length;
    for (let i = 0; i < len; i++) {
        const ch = val.charAt(i);
        const isNumEnglish = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z');
        if (!isNumEnglish) {
            await $c.win.alert(aDesc + " - " + "숫자나 영문 대문자만 입력하십시오.");
            setTimeout(function() {
                    $("#ipt_glblIsinCd").select();
                }, 10);
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chg_forn_com_yn
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.chg_forn_com_yn = async function (obj) {
    /* sdd-asis-lifecycle:begin chg_forn_com_yn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let isur_cd = $c.util.getComponent('ipt_isurCd').getValue(); if (isur_cd == null) { isur_cd = ''; }
    const cntr_cd = $c.util.getComponent('ipt_cntrCd').getValue();
    if ($c.str.getByteLength(isur_cd) != 0) {
        if (cntr_cd === '410' && obj === 'Y') {
            if (await $c.win.confirm("국내발행기관이 외국기업을 선택하셨습니다. 진행하시겠습니까?")) {
                $c.util.getComponent('ipt_glblIsinCd').setValue("");
                $c.util.getComponent("ipt_glblIsinCd").setStyle("background", "#FFFFFF");
                $c.util.getComponent('ipt_glblIsinCd').setDisabled(false);
                scwin.setGlblIsinComment('I');
                $c.util.getComponent('ipt_fornComYn').setValue("Y");
                $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("I");
                $("#dom_forn_isu_tp_cd_I").prop("checked", true);
            } else {
                $("#forn_com_yn_N").prop("checked", true);
                $("#dom_forn_isu_tp_cd_D").prop("checked", true);
            }
        } else {
            if (cntr_cd !== '410' && obj === 'N') {
                if (await $c.win.confirm("해외발행기관이 국내기업을 선택하셨습니다. 진행하시겠습니까?")) {
                    $c.util.getComponent("ipt_glblIsinCd").setStyle("background", "#e2e2e2");
                    $c.util.getComponent('ipt_glblIsinCd').setDisabled(true);
                    scwin.setGlblIsinComment('D');
                    $c.util.getComponent('ipt_fornComYn').setValue("N");
                    $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("D");
                    $("#dom_forn_isu_tp_cd_D").prop("checked", true);
                } else {
                    $("#forn_com_yn_Y").prop("checked", true);
                    $("#dom_forn_isu_tp_cd_I").prop("checked", true);
                }
            } else {
                if (cntr_cd !== '410' && obj === 'Y') {
                    $c.util.getComponent('ipt_glblIsinCd').setValue("");
                    $c.util.getComponent("ipt_glblIsinCd").setStyle("background", "#FFFFFF");
                    $c.util.getComponent('ipt_glblIsinCd').setDisabled(false);
                    scwin.setGlblIsinComment('I');
                    $c.util.getComponent('ipt_fornComYn').setValue("Y");
                    $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("I");
                    $("#dom_forn_isu_tp_cd_I").prop("checked", true);
                } else {
                    if (cntr_cd === '410' && obj === 'N') {
                        $c.util.getComponent('ipt_glblIsinCd').setValue("");
                        $c.util.getComponent("ipt_glblIsinCd").setStyle("background", "#e2e2e2");
                        $c.util.getComponent('ipt_glblIsinCd').setDisabled(true);
                        scwin.setGlblIsinComment('D');
                        $c.util.getComponent('ipt_fornComYn').setValue("N");
                        $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("D");
                        $("#dom_forn_isu_tp_cd_D").prop("checked", true);
                    }
                }
            }
        }
    }
    if (obj === 'Y') {
        $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("I");
        $("#dom_forn_isu_tp_cd_I").prop("checked", true);
    } else {
        $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("D");
        $("#dom_forn_isu_tp_cd_D").prop("checked", true);
    }
    /* sdd-asis-lifecycle:end */
};


